WITH catalog_agg AS (SELECT cs.cs_bill_customer_sk AS customer_sk, SUM(cs.cs_net_paid) AS catalog_net_paid, SUM(cs.cs_net_profit) AS catalog_net_profit, COUNT(*) AS catalog_orders, SUM(CASE WHEN sm.sm_type = 'AIR' THEN 1 ELSE 0 END) AS air_orders_catalog FROM catalog_sales cs JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk GROUP BY cs.cs_bill_customer_sk), web_agg AS (SELECT ws.ws_bill_customer_sk AS customer_sk, SUM(ws.ws_net_paid) AS web_net_paid, SUM(ws.ws_net_profit) AS web_net_profit, COUNT(*) AS web_orders, SUM(CASE WHEN sm.sm_type = 'AIR' THEN 1 ELSE 0 END) AS air_orders_web FROM web_sales ws JOIN ship_mode sm ON ws.ws_ship_mode_sk = sm.sm_ship_mode_sk GROUP BY ws.ws_bill_customer_sk) SELECT COALESCE(c.customer_sk, w.customer_sk) AS customer_sk, COALESCE(c.catalog_net_paid, 0) + COALESCE(w.web_net_paid, 0) AS total_net_paid, COALESCE(c.catalog_net_profit, 0) + COALESCE(w.web_net_profit, 0) AS total_net_profit, (COALESCE(c.catalog_net_profit, 0) + COALESCE(w.web_net_profit, 0)) / NULLIF(COALESCE(c.catalog_net_paid, 0) + COALESCE(w.web_net_paid, 0), 0) AS profit_margin, CASE WHEN (COALESCE(c.air_orders_catalog, 0) + COALESCE(w.air_orders_web, 0)) * 2 > (COALESCE(c.catalog_orders, 0) + COALESCE(w.web_orders, 0)) THEN 'Dominant AIR' ELSE 'Other' END AS ship_mode_preference, NTILE(4) OVER (ORDER BY (COALESCE(c.catalog_net_paid, 0) + COALESCE(w.web_net_paid, 0)) DESC) AS revenue_quartile FROM catalog_agg c FULL OUTER JOIN web_agg w ON c.customer_sk = w.customer_sk ORDER BY total_net_paid DESC LIMIT 20
